<?php
declare(strict_types=1);
require_once __DIR__.'/applications.php';require_once __DIR__.'/attachments.php';
final class LifeApplicationDocuments {
 public function __construct(private LifeApplications $apps,private array $config=[]){ }
 public function dir():string{$dir=life_attachment_dir($this->config,$this->apps->store->tenantId).'/applications';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new LifeError('Private document storage is unavailable.',503);return $dir;}
 public function path(array $document):string{return $this->dir().'/'.LifeApplications::id($document['fileId']);}
 public static function docxText(string $path):array{if(!class_exists('ZipArchive')||!class_exists('DOMDocument'))throw new LifeError('Word document support is unavailable on this server.',503);$zip=new ZipArchive();if($zip->open($path)!==true)throw new LifeError('Choose a valid Word document.');try{if($zip->numFiles>2000)throw new LifeError('This Word document is too complex.');$total=0;for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$total+=$stat['size'];if($stat['size']>20*1024*1024||$total>30*1024*1024||str_contains(strtolower($stat['name']),'vbaproject'))throw new LifeError('Use a small Word document without macros.');}$xml=$zip->getFromName('word/document.xml');if(!is_string($xml)||strlen($xml)>2*1024*1024)throw new LifeError('Choose a valid Word document.');}finally{$zip->close();}$dom=new DOMDocument();if(!@$dom->loadXML($xml,LIBXML_NONET)||$dom->doctype)throw new LifeError('The Word document could not be read safely.');$x=new DOMXPath($dom);$x->registerNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$paragraphs=[];foreach($x->query('//w:p') as $p){$text='';foreach($x->query('.//w:t',$p) as $t)$text.=$t->textContent;$paragraphs[]=$text;}if(strlen(implode("\n",$paragraphs))>40000)throw new LifeError('Use a document with up to 40,000 characters.');return $paragraphs;}
 public static function validateFile(string $path,string $name,int $size):string{if($size<1||$size>5*1024*1024)throw new LifeError('Choose a document up to 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if($ext==='docx'){if(!in_array($mime,['application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/octet-stream'],true))throw new LifeError('Choose a valid Word document.');self::docxText($path);return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';}if(!in_array($mime,['application/pdf','text/plain','image/jpeg','image/png','image/webp'],true))throw new LifeError('Use Word, PDF, text, JPEG, PNG or WebP.');return $mime;}
 private function replay(array $input,array $expected):?array{$key=(string)($input['requestId']??'');if($key==='')return null;$r=$this->apps->read();foreach($r['state']['receipts'] as $receipt)if($receipt['requestId']===$key){if($receipt['operation']!=='document.add')throw new LifeError('This save request belongs to another change.',409);$doc=LifeApplications::find($r['state'],'documents',$receipt['recordId']);foreach($expected as $field=>$value)if(($doc[$field]??'')!==$value)throw new LifeError('This save request already created a different document.',409);return $r+['receipt'=>$receipt];}return null;}
 public function upload(array $input):array{$f=$_FILES['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)throw new LifeError('Choose a document up to 5 MB.');$mime=self::validateFile($f['tmp_name'],$f['name'],(int)$f['size']);$replay=$this->replay($input,['trackerId'=>$input['trackerId']??'','categoryId'=>$input['categoryId']??'','opportunityId'=>$input['opportunityId']??'','name'=>basename($f['name']),'mime'=>$mime,'size'=>(int)$f['size']]);if($replay){$old=LifeApplications::find($replay['state'],'documents',$replay['receipt']['recordId']);if(!hash_equals(hash_file('sha256',$this->path($old)),hash_file('sha256',$f['tmp_name'])))throw new LifeError('This save request already uploaded different content.',409);return $replay;}$id=LifeStore::id();$path=$this->dir().'/'.$id;$text=$mime==='text/plain'?(string)file_get_contents($f['tmp_name']):($mime==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'?implode("\n",self::docxText($f['tmp_name'])):'');if(!move_uploaded_file($f['tmp_name'],$path))throw new LifeError('The document could not be saved.',503);chmod($path,0600);try{return $this->apps->mutate((int)($input['version']??0),'document.add',array_merge($input,['id'=>'','preferred'=>($input['preferred']??'')==='1','fileId'=>$id,'name'=>basename($f['name']),'mime'=>$mime,'size'=>(int)$f['size'],'text'=>$text]),(string)($input['requestId']??''));}catch(Throwable $e){unlink($path);throw $e;}}
 public function download(string $id):never{$doc=LifeApplications::find($this->apps->read()['state'],'documents',$id,true);$path=$this->path($doc);if(!is_file($path))throw new LifeError('Document not found.',404);header('Content-Type: '.$doc['mime']);header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($doc['name']));readfile($path);exit;}
 public function saveText(int $version,array $args):array{$text=LifeStore::text($args['text']??'',40000,true);$replay=$this->replay($args,['trackerId'=>$args['trackerId']??'','categoryId'=>$args['categoryId']??'','opportunityId'=>$args['opportunityId']??'','parentId'=>$args['parentId']??'','name'=>LifeStore::text($args['name']??'Application draft',180,true).'.txt','text'=>$text]);if($replay)return $replay;$id=LifeStore::id();$path=$this->dir().'/'.$id;if(file_put_contents($path,$text)===false)throw new LifeError('The document could not be saved.',503);chmod($path,0600);try{return $this->apps->mutate($version,'document.add',array_merge($args,['fileId'=>$id,'name'=>LifeStore::text($args['name']??'Application draft',180,true).'.txt','mime'=>'text/plain','size'=>strlen($text),'text'=>$text]),(string)($args['requestId']??''));}catch(Throwable $e){unlink($path);throw $e;}}
 /** Copy the complete Word package; replace only selected paragraphs, retaining paragraph/run styles. */
 public function saveWord(int $version,array $args):array{$s=$this->apps->read()['state'];$base=LifeApplications::find($s,'documents',$args['parentId']??'',true);if($base['mime']!=='application/vnd.openxmlformats-officedocument.wordprocessingml.document')throw new LifeError('Choose an editable Word base document.');$paragraphs=self::docxText($this->path($base));$changes=$args['changes']??[];if(!is_array($changes)||count($changes)>300)throw new LifeError('Choose up to 300 paragraph changes.');$id=LifeStore::id();$path=$this->dir().'/'.$id;if(!copy($this->path($base),$path))throw new LifeError('The copy could not be created.',503);chmod($path,0600);try{$zip=new ZipArchive();if($zip->open($path)!==true)throw new LifeError('The copy could not be edited.',503);try{$dom=new DOMDocument();$dom->loadXML($zip->getFromName('word/document.xml'),LIBXML_NONET);$x=new DOMXPath($dom);$x->registerNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$nodes=$x->query('//w:p');$seen=[];foreach($changes as $change){$i=$change['index']??null;if(!is_int($i)||$i<0||$i>=count($paragraphs)||isset($seen[$i]))throw new LifeError('Check the paragraph selection.');$seen[$i]=true;$text=LifeStore::text($change['text']??'',4000);$p=$nodes->item($i);if($x->query('.//w:drawing|.//w:fldChar',$p)->length)throw new LifeError('Keep paragraphs containing graphics or fields unchanged.');$texts=$x->query('.//w:t',$p);if($texts->length){$texts->item(0)->textContent=$text;$texts->item(0)->setAttribute('xml:space','preserve');for($j=1;$j<$texts->length;$j++)$texts->item($j)->textContent='';}elseif($text!==''){$run=$dom->createElementNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main','w:r');$t=$dom->createElementNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main','w:t');$t->textContent=$text;$run->appendChild($t);$p->appendChild($run);}$paragraphs[$i]=$text;}$zip->addFromString('word/document.xml',$dom->saveXML());}finally{$zip->close();}$replay=$this->replay($args,['trackerId'=>$base['trackerId'],'parentId'=>$base['id'],'opportunityId'=>$args['opportunityId']??'','name'=>LifeStore::text($args['name']??'Tailored CV',180,true).'.docx','text'=>implode("\n",$paragraphs)]);if($replay){unlink($path);return $replay;}return $this->apps->mutate($version,'document.add',array_merge($args,['trackerId'=>$base['trackerId'],'fileId'=>$id,'name'=>LifeStore::text($args['name']??'Tailored CV',180,true).'.docx','mime'=>$base['mime'],'size'=>filesize($path),'text'=>implode("\n",$paragraphs)]),(string)($args['requestId']??''));}catch(Throwable $e){unlink($path);throw $e;}}
}
